async function loadTrackerGraph() {
  try {
    // Fetch the historical log file generated by your GitHub Actions workflow
    const response = await fetch('./history.json');
    if (!response.ok) throw new Error('History log file not generated yet');
    
    const historyData = await response.json();

    // Map time arrays and player metrics out of the JSON
    const timestamps = historyData.map(log => log.time);
    const playerCounts = historyData.map(log => log.players);

    const ctx = document.getElementById('playerChart').getContext('2d');
    new Chart(ctx, {
      type: 'line',
      data: {
        labels: timestamps,
        datasets: [{
          label: 'Active Players Online',
          data: playerCounts,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.1)',
          borderWidth: 3,
          pointBackgroundColor: '#38bdf8',
          pointRadius: 2,
          tension: 0.3,
          fill: true
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: '#94a3b8', font: { size: 14 } }
          }
        },
        scales: {
          x: {
            grid: { color: '#334155' },
            ticks: { color: '#94a3b8' }
          },
          y: {
            beginAtZero: true,
            grid: { color: '#334155' },
            ticks: { color: '#94a3b8' }
          }
        }
      }
    });
  } catch (err) {
    console.error("Initialization error:", err);
    document.getElementById('chartContainer').innerHTML = `
      <div class="error-msg">
        📊 Waiting for the automated cloud bot to run its first sync cycle...
        <span class="error-subtext">
          (This will clear up automatically within 10 minutes when history.json is built)
        </span>
      </div>
    `;
  }
}

// Fire up the mapping workflow when the browser finishes loading structural assets
window.addEventListener('DOMContentLoaded', loadTrackerGraph);
